CREATE TABLE users (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL,
 display_name VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'INVESTOR', enabled BOOLEAN NOT NULL DEFAULT TRUE,
 opened BOOLEAN NOT NULL DEFAULT FALSE, initial_granted BOOLEAN NOT NULL DEFAULT FALSE, risk_level INT NOT NULL DEFAULT 0,
 risk_expires_at DATE NULL, default_trading_account_id BIGINT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE risk_assessments(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,answers VARCHAR(100) NOT NULL,risk_level INT NOT NULL,expires_at DATE NOT NULL,created_at DATETIME NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE bank_cards (
 id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,bank_name VARCHAR(80) NOT NULL,sim_number VARCHAR(60) NOT NULL UNIQUE,
 holder_name VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',receive_state VARCHAR(20) NOT NULL DEFAULT 'RECEIVABLE',
 single_limit DECIMAL(20,2) NOT NULL DEFAULT 1000000,daily_limit DECIMAL(20,2) NOT NULL DEFAULT 1000000,
 request_key VARCHAR(100) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,request_key),FOREIGN KEY(user_id) REFERENCES users(id)
);
CREATE TABLE trading_accounts (
 id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,account_no VARCHAR(60) NOT NULL UNIQUE,bank_card_id BIGINT NOT NULL,
 binding_version BIGINT NOT NULL DEFAULT 1,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',debit_frozen BOOLEAN NOT NULL DEFAULT FALSE,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(bank_card_id) REFERENCES bank_cards(id)
);
CREATE TABLE card_bindings(id BIGINT PRIMARY KEY AUTO_INCREMENT,trading_account_id BIGINT NOT NULL,bank_card_id BIGINT NOT NULL,binding_version BIGINT NOT NULL,change_request_id BIGINT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(trading_account_id,binding_version));
CREATE TABLE wallets(trading_account_id BIGINT PRIMARY KEY,available DECIMAL(20,2) NOT NULL DEFAULT 0,frozen DECIMAL(20,2) NOT NULL DEFAULT 0,FOREIGN KEY(trading_account_id) REFERENCES trading_accounts(id),CHECK(available>=0),CHECK(frozen>=0));
CREATE TABLE cash_entries(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,trading_account_id BIGINT NOT NULL,source_type VARCHAR(40) NOT NULL,source_id VARCHAR(100) NOT NULL,event_type VARCHAR(40) NOT NULL,available_delta DECIMAL(20,2) NOT NULL,frozen_delta DECIMAL(20,2) NOT NULL,amount DECIMAL(20,2) NOT NULL,created_at DATETIME NOT NULL,UNIQUE(trading_account_id,source_type,source_id,event_type));
CREATE TABLE registrars(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL);
CREATE TABLE fund_classes (
 id BIGINT PRIMARY KEY AUTO_INCREMENT,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,type VARCHAR(20) NOT NULL,
 manager VARCHAR(100) NOT NULL,registrar_id BIGINT NOT NULL,risk_level INT NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'OPEN',
 purchase_rate DECIMAL(12,8) NOT NULL DEFAULT 0,redemption_rate DECIMAL(12,8) NOT NULL DEFAULT 0,
 min_purchase DECIMAL(20,2) NOT NULL DEFAULT 10,min_redemption DECIMAL(24,4) NOT NULL DEFAULT 1,
 purchase_open BOOLEAN NOT NULL DEFAULT TRUE,redemption_open BOOLEAN NOT NULL DEFAULT TRUE,cutoff_time TIME NOT NULL DEFAULT '15:00:00',
 confirmation_days INT NOT NULL DEFAULT 1,payment_days INT NOT NULL DEFAULT 3,rule_version INT NOT NULL DEFAULT 1,
 FOREIGN KEY(registrar_id) REFERENCES registrars(id)
);
CREATE TABLE fee_tiers(id BIGINT PRIMARY KEY AUTO_INCREMENT,fund_class_id BIGINT NOT NULL,min_amount DECIMAL(20,2) NOT NULL DEFAULT 0,rate DECIMAL(12,8) NOT NULL,fixed_fee DECIMAL(20,2) NULL,UNIQUE(fund_class_id,min_amount));
CREATE TABLE fund_accounts(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,registrar_id BIGINT NOT NULL,account_no VARCHAR(60) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',UNIQUE(user_id,registrar_id));
CREATE TABLE trading_fund_accounts(trading_account_id BIGINT NOT NULL,fund_account_id BIGINT NOT NULL,PRIMARY KEY(trading_account_id,fund_account_id));
CREATE TABLE trading_calendar(date DATE PRIMARY KEY,open BOOLEAN NOT NULL);
CREATE TABLE nav_records(id BIGINT PRIMARY KEY AUTO_INCREMENT,fund_class_id BIGINT NOT NULL,date DATE NOT NULL,nav DECIMAL(20,6) NOT NULL,published BOOLEAN NOT NULL DEFAULT TRUE,used BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(fund_class_id,date));
CREATE TABLE favorites(user_id BIGINT NOT NULL,fund_class_id BIGINT NOT NULL,PRIMARY KEY(user_id,fund_class_id));
CREATE TABLE order_groups(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,request_key VARCHAR(100) NOT NULL,request_fingerprint VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'SUBMITTED',created_at DATETIME NOT NULL,UNIQUE(user_id,request_key));
CREATE TABLE orders (
 id BIGINT PRIMARY KEY AUTO_INCREMENT,order_no VARCHAR(60) NOT NULL UNIQUE,user_id BIGINT NOT NULL,type VARCHAR(30) NOT NULL,
 fund_class_id BIGINT NOT NULL,trading_account_id BIGINT NOT NULL,source_card_id BIGINT NOT NULL,binding_version BIGINT NOT NULL,
 fund_account_id BIGINT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'SUBMITTED',amount DECIMAL(20,2) NOT NULL DEFAULT 0,shares DECIMAL(24,4) NOT NULL DEFAULT 0,
 nav DECIMAL(20,6) NULL,fee DECIMAL(20,2) NOT NULL DEFAULT 0,net_amount DECIMAL(20,2) NOT NULL DEFAULT 0,rounding_difference DECIMAL(24,12) NOT NULL DEFAULT 0,
 application_date DATE NOT NULL,confirmation_date DATE NOT NULL,payment_date DATE NOT NULL,reason VARCHAR(500) NULL,
 group_id BIGINT NULL,request_key VARCHAR(100) NOT NULL,request_fingerprint VARCHAR(64) NOT NULL,
 purchase_rate DECIMAL(12,8) NOT NULL,redemption_rate DECIMAL(12,8) NOT NULL,fixed_fee DECIMAL(20,2) NULL,
 risk_level INT NOT NULL,rule_version INT NOT NULL,cutoff_time TIME NOT NULL,created_at DATETIME NOT NULL,
 UNIQUE(user_id,request_key),INDEX(status,confirmation_date),FOREIGN KEY(trading_account_id) REFERENCES trading_accounts(id)
);
CREATE TABLE debit_quota_entries(id BIGINT PRIMARY KEY AUTO_INCREMENT,trading_account_id BIGINT NOT NULL,source_type VARCHAR(40) NOT NULL,source_id VARCHAR(100) NOT NULL,date DATE NOT NULL,amount DECIMAL(20,2) NOT NULL,released BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE(trading_account_id,source_type,source_id));
CREATE TABLE order_events(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,event_type VARCHAR(40) NOT NULL,created_at DATETIME NOT NULL,UNIQUE(order_id,event_type));
CREATE TABLE position_lots (
 id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,trading_account_id BIGINT NOT NULL,fund_class_id BIGINT NOT NULL,
 source_card_id BIGINT NOT NULL,fund_account_id BIGINT NOT NULL,shares DECIMAL(24,4) NOT NULL,frozen_shares DECIMAL(24,4) NOT NULL DEFAULT 0,
 cost DECIMAL(20,2) NOT NULL,acquired_date DATE NOT NULL,source_type VARCHAR(40) NOT NULL,source_id VARCHAR(100) NOT NULL,
 UNIQUE(trading_account_id,fund_class_id,source_type,source_id,source_card_id),INDEX(trading_account_id,fund_class_id,acquired_date),CHECK(shares>=0),CHECK(frozen_shares>=0),CHECK(shares>=frozen_shares)
);
CREATE TABLE order_lot_allocations(id BIGINT PRIMARY KEY AUTO_INCREMENT,order_id BIGINT NOT NULL,lot_id BIGINT NOT NULL,shares DECIMAL(24,4) NOT NULL,cost DECIMAL(20,2) NOT NULL,source_card_id BIGINT NOT NULL,fund_account_id BIGINT NOT NULL,acquired_date DATE NOT NULL,UNIQUE(order_id,lot_id));
CREATE TABLE share_entries(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,trading_account_id BIGINT NOT NULL,fund_class_id BIGINT NOT NULL,lot_id BIGINT NOT NULL,source_type VARCHAR(40) NOT NULL,source_id VARCHAR(100) NOT NULL,event_type VARCHAR(40) NOT NULL,shares_delta DECIMAL(24,4) NOT NULL,frozen_delta DECIMAL(24,4) NOT NULL,cost_delta DECIMAL(20,2) NOT NULL,created_at DATETIME NOT NULL,UNIQUE(trading_account_id,fund_class_id,lot_id,source_type,source_id,event_type));
CREATE TABLE payouts (
 id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,trading_account_id BIGINT NOT NULL,source_card_id BIGINT NOT NULL,target_card_id BIGINT NOT NULL,
 target_binding_version BIGINT NOT NULL,authorization_id BIGINT NULL,source_type VARCHAR(40) NOT NULL,source_id VARCHAR(100) NOT NULL,
 amount DECIMAL(20,2) NOT NULL,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',reason VARCHAR(500) NULL,paid_at DATETIME NULL,created_at DATETIME NOT NULL,
 UNIQUE(trading_account_id,source_type,source_id,source_card_id),INDEX(status,due_date)
);
CREATE TABLE payout_route_changes(id BIGINT PRIMARY KEY AUTO_INCREMENT,payout_id BIGINT NOT NULL,old_card_id BIGINT NOT NULL,new_card_id BIGINT NOT NULL,authorization_id BIGINT NOT NULL,reason VARCHAR(500) NOT NULL,created_at DATETIME NOT NULL,UNIQUE(payout_id,authorization_id));
CREATE TABLE job_runs(id BIGINT PRIMARY KEY AUTO_INCREMENT,type VARCHAR(30) NOT NULL,date DATE NOT NULL,status VARCHAR(20) NOT NULL,processed INT NOT NULL DEFAULT 0,waiting INT NOT NULL DEFAULT 0,failed INT NOT NULL DEFAULT 0,details TEXT NULL,created_at DATETIME NOT NULL);
CREATE TABLE notifications(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,type VARCHAR(40) NOT NULL,source_id VARCHAR(100) NOT NULL,title VARCHAR(120) NOT NULL,message VARCHAR(1000) NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME NOT NULL,UNIQUE(user_id,type,source_id));
CREATE TABLE audit_events(id BIGINT PRIMARY KEY AUTO_INCREMENT,actor_id BIGINT NULL,action VARCHAR(80) NOT NULL,object_type VARCHAR(60) NOT NULL,object_id BIGINT NOT NULL,reason VARCHAR(1000) NOT NULL,created_at DATETIME NOT NULL);
CREATE TABLE announcements(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,created_at DATETIME NOT NULL);
CREATE TABLE app_settings(name VARCHAR(60) PRIMARY KEY,value VARCHAR(100) NOT NULL);
CREATE TABLE SPRING_SESSION (PRIMARY_ID CHAR(36) NOT NULL,SESSION_ID CHAR(36) NOT NULL,CREATION_TIME BIGINT NOT NULL,LAST_ACCESS_TIME BIGINT NOT NULL,MAX_INACTIVE_INTERVAL INT NOT NULL,EXPIRY_TIME BIGINT NOT NULL,PRINCIPAL_NAME VARCHAR(100),CONSTRAINT SPRING_SESSION_PK PRIMARY KEY(PRIMARY_ID),UNIQUE INDEX SPRING_SESSION_IX1(SESSION_ID),INDEX SPRING_SESSION_IX2(EXPIRY_TIME),INDEX SPRING_SESSION_IX3(PRINCIPAL_NAME)) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;
CREATE TABLE SPRING_SESSION_ATTRIBUTES(SESSION_PRIMARY_ID CHAR(36) NOT NULL,ATTRIBUTE_NAME VARCHAR(200) NOT NULL,ATTRIBUTE_BYTES BLOB NOT NULL,CONSTRAINT SPRING_SESSION_ATTRIBUTES_PK PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME),CONSTRAINT SPRING_SESSION_ATTRIBUTES_FK FOREIGN KEY(SESSION_PRIMARY_ID) REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE) ENGINE=InnoDB ROW_FORMAT=DYNAMIC;
